style:
margin: 0;
padding: 0;
border: none;
display: flex;
flex-direction: column;
gap: 2px;

.f-radio {
  position: relative;

  input {
    position: fixed !important;
    left: -9999px !important;
    height: 0;
    width: 0;

    &:checked+label {
      color: var(--bg-surface);
    }

    &:checked+label::before {
      border-color: var(--bg-surface);
    }

    &:checked+label::after {
      opacity: 1;
    }
  }

  label {
    display: inline-block;
    position: relative;
    cursor: pointer;
    opacity: 1;
    line-height: 17px;
    padding: 0 0 0 28px;
    transition: all 0.2s ease-in-out;

    &:hover {
      color: var(--bg-surface);
    }

    &:hover::before {
      border-color: var(--bg-surface);
    }

    &::before,
    &::after {
      display: block;
      transition: all 0.2s ease-in-out;
      content: '';
      position: absolute;
      left: 0;
      top: 0;
    }

    &::before {
      border-radius: 50%;
      width: 16px;
      height: 16px;
      border: 2px solid var(--text-main);
      background: transparent;
    }

    &::after {
      width: 10px;
      height: 10px;
      border-radius: 100%;
      top: -3px;
      left: -3px;
      transform: translate(6px, 6px);
      border: 2px solid var(--bg-surface);
      background-color: var(--bg-surface);
      opacity: 0;
    }
  }
}
